44	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
45	
46	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
47	    int64_t formerNum = usedCoreNum - 1;
48	    int64_t formerLength = totalLengthCoreAlign;
49	    int64_t tailLength = totalLength - formerNum * formerLength;
50	
51	    // ---- UB 级 tiling (核内切分) ----
52	    // bufferCoefficient from UB allocation table:
53	    //   float32: 20 (inQueueX * 2 + outQueueY * 2 + tempBuffer * 1)
54	    //   float16/bfloat16: 16 (inQueueX * 2 + outQueueY * 2 + tempBuffer * 2)
55	    int64_t bufferCoefficient = (dtypeSize == 4) ? 20 : 16;
56	    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
57	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
58	    if (dtypeSize == 0) { dtypeSize = 1; }
59	    int64_t alignElements = 32 / dtypeSize;
60	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
61	
62	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
63	
64	    EXEC_KERNEL_CMD(abs, blockDim,
65	                    self, output,
66	                    formerNum, formerLength, tailLength, tileLength, dtypeSize);
67	
68	    return output;
69	}
70	
71	}  // namespace ascend_kernel
