10	
11	#include "kernel_operator.h"
12	
13	constexpr int32_t BUFFER_NUM = 2;
14	
15	template <typename T>
16	class KernelAbs {
17	public:
18	    __aicore__ inline KernelAbs() {}
19	
20	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
21	                                int64_t formerNum, int64_t formerLength,
22	                                int64_t tailLength, int64_t tileLength)
23	    {
24	        int64_t blockIdx = AscendC::GetBlockIdx();
25	
26	        if (blockIdx < formerNum) {
27	            this->blockLength = formerLength;
28	            int64_t offset = formerLength * blockIdx;
29	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
30	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
31	        } else {
32	            this->blockLength = tailLength;
33	            int64_t tailIdx = blockIdx - formerNum;
34	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
35	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
36	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
37	        }
38	
39	        this->tileLength = tileLength;
40	
41	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
42	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
43	        if constexpr (sizeof(T) == sizeof(half)) {
44	            pipe.InitBuffer(tmpBuf, tileLength * sizeof(float) * 2);
45	        }
46	    }
47	
48	    __aicore__ inline void Process()
49	    {
50	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
51	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
52	
53	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
54	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
55	
56	        for (int64_t i = 0; i < tileNum - 1; ++i) {
57	            CopyIn(i, this->tileLength);
58	            Compute(i, this->tileLength);
59	            CopyOut(i, this->tileLength);
60	        }
61	        if (tileNum > 0) {
62	            CopyIn(tileNum - 1, alignedTailLen);
63	            Compute(tileNum - 1, alignedTailLen);
64	            CopyOut(tileNum - 1, alignedTailLen);
65	        }
66	    }
67	
68	private:
69	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
70	    {
71	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
72	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
73	        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
74	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams, padParams);
75	        inQueueX.EnQue(xLocal);
76	    }
77	
78	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
79	    {
80	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
81	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
82	
83	        if constexpr (sizeof(T) == sizeof(float)) {
84	            // float32: direct compute
85	            AscendC::Abs(yLocal, xLocal, curTileLength);
86	        } else {
87	            // float16/bfloat16: cast up to fp32, compute, cast down
88	            AscendC::LocalTensor<float> xFp32 = tmpBuf.Get<float>();
89	            AscendC::LocalTensor<float> yFp32 = tmpBuf.Get<float>();
90	            xFp32.SetSize(curTileLength);
91	            yFp32.SetSize(curTileLength);
92	            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
93	            AscendC::Abs(yFp32, xFp32, curTileLength);
94	            AscendC::Cast(yLocal, yFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
95	        }
96	
97	        outQueueY.EnQue<T>(yLocal);
98	        inQueueX.FreeTensor(xLocal);
99	    }
100	
101	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
102	    {
103	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
104	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
105	        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
106	        outQueueY.FreeTensor(yLocal);
107	    }
108	
109	private:
110	    AscendC::TPipe pipe;
111	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
112	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
113	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf;
114	    AscendC::GlobalTensor<T> xGm;
115	    AscendC::GlobalTensor<T> yGm;
116	    int64_t blockLength;
117	    int64_t tileLength;
118	};
119	
120	extern "C" __global__ __aicore__ void abs(GM_ADDR x, GM_ADDR y,
121	                                           int64_t formerNum, int64_t formerLength,
122	                                           int64_t tailLength, int64_t tileLength,
123	                                           int64_t dtypeSize)
124	{
125	    if (dtypeSize == 2) {
126	        KernelAbs<half> op;
127	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
128	        op.Process();
129	    } else {
130	        KernelAbs<float> op;
131	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
132	        op.Process();
133	    }
134	}
